mapper.sql:
LEFT JOIN (
    SELECT p.article_id AS article_id, COUNT(*) AS cnt
    FROM play_recording p
    WHERE p.update_time >= #{startTime}
      AND p.update_time < #{endTime}
    GROUP BY p.article_id
) pv ON pv.article_id = a.id

LEFT JOIN (
    SELECT l.like_obj_id AS article_id, COUNT(*) AS cnt
    FROM like_table l
    WHERE l.type = 0
      AND l.create_time >= #{startTime}
      AND l.create_time < #{endTime}
    GROUP BY l.like_obj_id
) pl ON pl.article_id = a.id

LEFT JOIN (
    SELECT c.article_id AS article_id, COUNT(*) AS cnt
    FROM comment c
    WHERE c.status = 0
      AND c.create_time >= #{startTime}
      AND c.create_time < #{endTime}
    GROUP BY c.article_id
) pc ON pc.article_id = a.id

LEFT JOIN (
    SELECT f.artice_id AS article_id, COUNT(*) AS cnt
    FROM favorites_table f
    WHERE f.create_time >= #{startTime}
      AND f.create_time < #{endTime}
    GROUP BY f.artice_id
) pf ON pf.article_id = a.id

LEFT JOIN (
    SELECT d.video_id AS article_id, COUNT(*) AS cnt
    FROM danmaku d
    WHERE d.create_time >= #{startTime}
      AND d.create_time < #{endTime}
    GROUP BY d.video_id
) pd ON pd.article_id = a.id

mapper.select:
SELECT 'view' AS metric,
       (p.update_time + #{tzOffset}) DIV #{dayMillis} AS dayIndex,
       COUNT(*) AS cnt
FROM play_recording p
INNER JOIN article a ON a.id = p.article_id
WHERE a.user_id = #{userId} AND a.status = #{status}
  AND p.update_time >= #{startTime} AND p.update_time < #{endTime}
GROUP BY (p.update_time + #{tzOffset}) DIV #{dayMillis}

UNION ALL

SELECT 'like',
       (l.create_time + #{tzOffset}) DIV #{dayMillis},
       COUNT(*)
FROM like_table l
INNER JOIN article a ON a.id = l.like_obj_id
WHERE a.user_id = #{userId} AND a.status = #{status}
  AND l.type = 0
  AND l.create_time >= #{startTime} AND l.create_time < #{endTime}
GROUP BY (l.create_time + #{tzOffset}) DIV #{dayMillis}

UNION ALL

SELECT 'comment',
       (c.create_time + #{tzOffset}) DIV #{dayMillis},
       COUNT(*)
FROM comment c
INNER JOIN article a ON a.id = c.article_id
WHERE a.user_id = #{userId} AND a.status = #{status}
  AND c.status = 0
  AND c.create_time >= #{startTime} AND c.create_time < #{endTime}
GROUP BY (c.create_time + #{tzOffset}) DIV #{dayMillis}

UNION ALL

SELECT 'favorite',
       (f.create_time + #{tzOffset}) DIV #{dayMillis},
       COUNT(*)
FROM favorites_table f
INNER JOIN article a ON a.id = f.artice_id
WHERE a.user_id = #{userId} AND a.status = #{status}
  AND f.create_time >= #{startTime} AND f.create_time < #{endTime}
GROUP BY (f.create_time + #{tzOffset}) DIV #{dayMillis}

UNION ALL

SELECT 'danmaku',
       (d.create_time + #{tzOffset}) DIV #{dayMillis},
       COUNT(*)
FROM danmaku d
INNER JOIN article a ON a.id = d.video_id
WHERE a.user_id = #{userId} AND a.status = #{status}
  AND d.create_time >= #{startTime} AND d.create_time < #{endTime}
GROUP BY (d.create_time + #{tzOffset}) DIV #{dayMillis}

UNION ALL

SELECT 'fans',
       (fw.create_time + #{tzOffset}) DIV #{dayMillis},
       COUNT(*)
FROM follow fw
WHERE fw.follow_user = #{userId}
  AND fw.create_time >= #{startTime} AND fw.create_time < #{endTime}
GROUP BY (fw.create_time + #{tzOffset}) DIV #{dayMillis}
